import { Component, OnInit, Output, EventEmitter, TemplateRef, ViewChild } from '@angular/core';
import { EventService } from 'src/app/core/services/event.service';
import { NgbOffcanvas } from '@ng-bootstrap/ng-bootstrap';
import { RootReducerState } from 'src/app/store';
import { Store } from '@ngrx/store';
import { initialState } from 'src/app/store/layouts/layout-reducers';
import {
  getBackgroundImage,
  getLayoutMode,
  getLayoutPosition,
  getLayoutTheme,
  getLayoutWith,
  getPreloader,
  getSidebarColor,
  getSidebarImage,
  getSidebarSize,
  getSidebarView,
  getSidebarVisibilitye,
  getTheme,
  getThemeColor,
  getTopbarColor,
} from 'src/app/store/layouts/layout-selector';
import {
  changeBackgrounImage,
  changeDataPreloader,
  changeLayoutPosition,
  changeLayoutWidth,
  changeMode,
  changeSidebarColor,
  changeSidebarImage,
  changeSidebarSize,
  changeSidebarView,
  changeSidebarVisibility,
  changeTheme,
  changeThemeColor,
  changeTopbar,
  changelayout,
} from 'src/app/store/layouts/layout-action';
import { CurrentUserServiceService } from 'src/app/services/utils/current-user-service/current-user-service.service';

@Component({
  selector: 'app-rightsidebar',
  templateUrl: './rightsidebar.component.html',
  styleUrls: ['./rightsidebar.component.scss'],
})

/**
 * Right Sidebar component
 */
export class RightsidebarComponent implements OnInit {
  layout: string | undefined;
  theme: string | undefined;
  themecolor: string | undefined;
  mode: string | undefined;
  width: string | undefined;
  position: string | undefined;
  topbar: string | undefined;
  size: string | undefined;
  sidebarView: string | undefined;
  sidebar: string | undefined;
  attribute: any;
  sidebarImage: any;
  sidebarVisibility: any;
  preLoader: any;
  grd: any;
  backgroundImage: any;

  @ViewChild('filtetcontent') filtetcontent!: TemplateRef<any>;
  @Output() settingsButtonClicked = new EventEmitter();

  constructor(
    private eventService: EventService,
    private offcanvasService: NgbOffcanvas,
    private store: Store<RootReducerState>,
    private currentUserService: CurrentUserServiceService
  ) {}

  ngOnInit(): void {
    // setTimeout(() => {
    //   if (this.offcanvasService.hasOpenOffcanvas() == false) {
    //     this.openEnd(this.filtetcontent);
    //   };
    // }, 1000);
    if (this.currentUserService.getThemeSettings() == null) {
      this.store.select('layout').subscribe(data => {
        this.layout = data.LAYOUT;
        this.theme = data.LAYOUT_THEME;
        this.themecolor = data.LAYOUT_THEME_COLOR;
        this.mode = data.LAYOUT_MODE;
        this.width = data.LAYOUT_WIDTH;
        this.position = data.LAYOUT_POSITION;
        this.topbar = data.TOPBAR;
        this.size = data.SIDEBAR_SIZE;
        this.sidebarView = data.SIDEBAR_VIEW;
        this.sidebar = data.SIDEBAR_COLOR;
        this.sidebarImage = data.SIDEBAR_IMAGE;
        this.preLoader = data.DATA_PRELOADER;
        this.sidebarVisibility = data.SIDEBAR_VISIBILITY;
      });
    } else {
      var data = this.currentUserService.getThemeSettings();
      this.layout = data.LAYOUT;
      this.theme = data.LAYOUT_THEME;
      this.themecolor = data.LAYOUT_THEME_COLOR;
      this.mode = data.LAYOUT_MODE;
      this.size = data.SIDEBAR_SIZE;
      this.width = data.LAYOUT_WIDTH;
      this.position = data.LAYOUT_POSITION;
      this.topbar = data.TOPBAR;
      this.sidebarView = data.SIDEBAR_VIEW;
      this.sidebar = data.SIDEBAR_COLOR;
      this.sidebarImage = data.SIDEBAR_IMAGE;
      this.preLoader = data.DATA_PRELOADER;
      this.changelayoutTheme(this.theme);
      if (this.theme!="horizontal") {
        this.changeLayout(this.layout);

      }
      this.changeColor(this.themecolor);
      this.changeLayoutMode(this.mode);
      this.changeSidebarSize(this.size);
      this.changeWidth(this.width, this.size);
      this.changePosition(this.position);
      this.changeTopColor(this.topbar);
      this.changeSidebar(this.sidebarView);
      this.changeSidebarColor(this.sidebar);
      this.changeSidebarImage(this.sidebarImage);
      this.changeBackgroundImage(this.backgroundImage);
      this.changeLoader(this.preLoader);
    }
  }
  saveTheme() {
    var data: any = <any>{};
    data.LAYOUT = this.layout;
    data.LAYOUT_THEME = this.theme;
    data.LAYOUT_THEME_COLOR = this.themecolor;
    data.LAYOUT_MODE = this.mode;
    data.SIDEBAR_SIZE = this.size;
    data.LAYOUT_WIDTH = this.width;
    data.LAYOUT_POSITION = this.position;
    data.TOPBAR = this.topbar;
    data.SIDEBAR_VIEW = this.sidebarView;
    data.SIDEBAR_COLOR = this.sidebar;
    data.SIDEBAR_IMAGE = this.sidebarImage;
    data.DATA_PRELOADER = this.preLoader;
    this.currentUserService.setThemeSettings(data);
  }
  ngAfterViewInit() {}

  /**
   * Change the layout onclick
   * @param layout Change the layout
   */
  changeLayout(layout: string) {
    this.layout = layout;
    this.saveTheme();
    this.attribute = layout;
    this.store.dispatch(changelayout({ layout }));
    this.store.select(getLayoutTheme).subscribe(layout => {
      document.documentElement.setAttribute('data-layout', layout);
    });
    setTimeout(() => {
      window.dispatchEvent(new Event('resize'));
    }, 100);
  }

  // Add Active Class
  addActive(grdSidebar: any) {
    this.grd = grdSidebar;
    document.documentElement.setAttribute('data-sidebar', grdSidebar);
    document.getElementById('collapseBgGradient')?.classList.toggle('show');
    document.getElementById('collapseBgGradient1')?.classList.add('active');
  }

  // Remove Active Class
  removeActive() {
    this.grd = '';
    document.getElementById('collapseBgGradient1')?.classList.remove('active');
    document.getElementById('collapseBgGradient')?.classList.remove('show');
  }

  // When the user clicks on the button, scroll to the top of the document
  topFunction() {
    document.body.scrollTop = 0;
    document.documentElement.scrollTop = 0;
  }

  //  Filter Offcanvas Set
  openEnd(content: TemplateRef<any>) {
    this.offcanvasService.open(content, { position: 'end' });

    setTimeout(() => {
      this.attribute = document.documentElement.getAttribute('data-layout');
      if (this.attribute == 'vertical') {
        var vertical = document.getElementById('customizer-layout01') as HTMLInputElement;
        if (vertical != null) {
          vertical.setAttribute('checked', 'true');
        }
      }
      if (this.attribute == 'horizontal') {
        const horizontal = document.getElementById('customizer-layout02');
        if (horizontal != null) {
          horizontal.setAttribute('checked', 'true');
        }
      }
      if (this.attribute == 'twocolumn') {
        const Twocolumn = document.getElementById('customizer-layout03');
        if (Twocolumn != null) {
          Twocolumn.setAttribute('checked', 'true');
        }
      }
      if (this.attribute == 'semibox') {
        const Twocolumn = document.getElementById('customizer-layout04');
        if (Twocolumn != null) {
          Twocolumn.setAttribute('checked', 'true');
        }
      }
    }, 100);
  }

  // Show Profile Sidebar
  showSidebarProgile(event: any) {
    if (event.target.checked == true) {
      document.documentElement.setAttribute('data-sidebar-user-show', '');
    } else {
      document.documentElement.removeAttribute('data-sidebar-user-show');
    }
  }

  // Theme Change
  changelayoutTheme(theme: string) {
    this.theme = theme;
    this.saveTheme();
    this.store.dispatch(changeTheme({ theme }));
    this.store.select(getTheme).subscribe(theme => {
      document.documentElement.setAttribute('data-theme', theme);
    });

    if (theme == 'saas') {
      const layout = 'horizontal';
      this.store.dispatch(changelayout({ layout }));
    } else if (theme == 'creative') {
      const layout = 'twocolumn';
      this.store.dispatch(changelayout({ layout }));
    } else {
      const layout = 'vertical';
      this.store.dispatch(changelayout({ layout }));
    }

    if (theme == 'galaxy') {
      this.eventService.changePrimengMode('dark');
      this.store.dispatch(changeMode({ mode: 'dark' }));
    } else {
      this.eventService.changePrimengMode('light');
      this.store.dispatch(changeMode({ mode: 'light' }));
    }

    if (theme == 'modern') {
      this.store.dispatch(changeSidebarSize({ sidebarSize: 'sm-hover' }));
    } else {
      this.store.dispatch(changeSidebarSize({ sidebarSize: 'lg' }));
    }

    setTimeout(() => {
      window.dispatchEvent(new Event('resize'));
    }, 100);
  }

